import{_ as e,o as i,c as a,a2 as t}from"./chunks/framework.CZqXuAiL.js";const k=JSON.parse('{"title":"Installation","description":"Install LiteShield XDP with the interactive installer or manually — prerequisites, verification, troubleshooting, and uninstall.","frontmatter":{"title":"Installation","description":"Install LiteShield XDP with the interactive installer or manually — prerequisites, verification, troubleshooting, and uninstall."},"headers":[],"relativePath":"liteshield-xdp/getting-started/installation.md","filePath":"liteshield-xdp/getting-started/installation.md","lastUpdated":null}'),n={name:"liteshield-xdp/getting-started/installation.md"};function l(d,s,p,o,h,r){return i(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><blockquote><p><strong>Get LiteShield XDP protecting your interface in under a minute.</strong> The installer builds from source, so it works on any distro with a supported package manager — no prebuilt binaries to trust.</p></blockquote><nav class="table-of-contents"><ul><li><a href="#prerequisites">Prerequisites</a></li><li><a href="#interactive-install">Interactive Install</a><ul><li><a href="#step-1-4-—-network-interface">Step 1/4 — Network interface</a></li><li><a href="#step-2-4-—-deployment-preset">Step 2/4 — Deployment preset</a></li><li><a href="#step-3-4-—-traffic-profile">Step 3/4 — Traffic profile</a></li><li><a href="#step-4-4-—-discord-alerts-optional">Step 4/4 — Discord alerts (optional)</a></li><li><a href="#what-happens-next">What happens next</a></li></ul></li><li><a href="#manual-install">Manual Install</a></li><li><a href="#post-install-verification">Post-Install Verification</a></li><li><a href="#troubleshooting">Troubleshooting</a></li><li><a href="#uninstall">Uninstall</a></li></ul></nav><hr><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Requirement</th><th>Minimum</th><th>Check</th></tr></thead><tbody><tr><td>Kernel</td><td>Linux <strong>5.15+</strong></td><td><code>uname -r</code></td></tr><tr><td>Kernel BTF</td><td><code>CONFIG_DEBUG_INFO_BTF=y</code></td><td><code>ls /sys/kernel/btf/vmlinux</code></td></tr><tr><td>Go</td><td><strong>1.22+</strong></td><td><code>go version</code></td></tr><tr><td>Build tools</td><td><code>clang</code>, <code>llvm-strip</code>, <code>bpftool</code>, <code>make</code></td><td><code>command -v clang</code></td></tr><tr><td>Privileges</td><td>root</td><td><code>id -u</code> → <code>0</code></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Don&#39;t have the build tools?</p><p>The installer detects missing dependencies and installs them automatically via your package manager — <code>apt</code>, <code>dnf</code>, <code>yum</code>, <code>pacman</code>, <code>apk</code>, and <code>zypper</code> are all supported. You only need root and a 5.15+ kernel with BTF.</p></div><div class="warning custom-block"><p class="custom-block-title">BTF is not optional</p><p>LiteShield builds a CO-RE eBPF object, which requires kernel BTF. If <code>/sys/kernel/btf/vmlinux</code> does not exist, the installer stops immediately. Virtually all modern distro kernels (Ubuntu 22.04+, Debian 12+, Fedora, Arch, Rocky/Alma 9+) ship BTF enabled.</p></div><hr><h2 id="interactive-install" tabindex="-1">Interactive Install <a class="header-anchor" href="#interactive-install" aria-label="Permalink to &quot;Interactive Install&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/AnAverageBeing/LiteShield-XDP/main/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span></span></code></pre></div><p>The installer runs four steps after pre-flight checks (kernel version, BTF, package manager, build tools):</p><h3 id="step-1-4-—-network-interface" tabindex="-1">Step 1/4 — Network interface <a class="header-anchor" href="#step-1-4-—-network-interface" aria-label="Permalink to &quot;Step 1/4 — Network interface&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[*] Step 1/4 — Network interface</span></span>
<span class="line"><span>    Available interfaces:</span></span>
<span class="line"><span>      - eth0             (up)</span></span>
<span class="line"><span>      - ens18            (up)</span></span>
<span class="line"><span>      - docker0          (down)</span></span>
<span class="line"><span>[?] Interface to protect [eth0]:</span></span></code></pre></div><p>Auto-detected from your default route. Press Enter to accept, or type another interface name.</p><h3 id="step-2-4-—-deployment-preset" tabindex="-1">Step 2/4 — Deployment preset <a class="header-anchor" href="#step-2-4-—-deployment-preset" aria-label="Permalink to &quot;Step 2/4 — Deployment preset&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[?] Preset (base thresholds):</span></span>
<span class="line"><span>    1) Personal</span></span>
<span class="line"><span>    2) Hosting</span></span>
<span class="line"><span>    3) Enterprise</span></span>
<span class="line"><span>[?] Choose [Hosting]:</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Preset</th><th>Intended for</th><th>Base PPS</th></tr></thead><tbody><tr><td><strong>Personal</strong></td><td>Home server behind a residential line</td><td>50,000</td></tr><tr><td><strong>Hosting</strong></td><td>VPS / shared hosting with moderate traffic</td><td>200,000</td></tr><tr><td><strong>Enterprise</strong></td><td>Dedicated server / high-traffic edge</td><td>1,000,000</td></tr></tbody></table><h3 id="step-3-4-—-traffic-profile" tabindex="-1">Step 3/4 — Traffic profile <a class="header-anchor" href="#step-3-4-—-traffic-profile" aria-label="Permalink to &quot;Step 3/4 — Traffic profile&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[?] Traffic type (scales the preset):</span></span>
<span class="line"><span>    1) Strict</span></span>
<span class="line"><span>    2) Balanced</span></span>
<span class="line"><span>    3) High</span></span>
<span class="line"><span>[?] Choose [Balanced]:</span></span></code></pre></div><p>The profile multiplies the preset&#39;s base rates: <strong>Strict = 0.5×</strong>, <strong>Balanced = 1.0×</strong>, <strong>High = 2.0×</strong>. The installer prints the effective thresholds so you can confirm before anything is written:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[*] Effective thresholds (Hosting / Balanced):</span></span>
<span class="line"><span>    pps=200000 syn=2000 udp=10000 icmp=500 new_src=500 flow_pps=20000 flow_bps=20000000</span></span></code></pre></div><h3 id="step-4-4-—-discord-alerts-optional" tabindex="-1">Step 4/4 — Discord alerts (optional) <a class="header-anchor" href="#step-4-4-—-discord-alerts-optional" aria-label="Permalink to &quot;Step 4/4 — Discord alerts (optional)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[?] Enable Discord webhook alerts? [y/N]: y</span></span>
<span class="line"><span>[?] Discord webhook URL: https://discord.com/api/webhooks/...</span></span>
<span class="line"><span>[?] Alert on rule_trigger (rate-limit violations)? [Y/n]: y</span></span>
<span class="line"><span>[?] Alert on ip_banned? [Y/n]: y</span></span>
<span class="line"><span>[?] Alert on new_source (new-IP flood)? [Y/n]: y</span></span></code></pre></div><p>The URL is validated against the Discord webhook format before continuing. Leave this off if you don&#39;t want alerts — you can add a webhook later with <code>liteshield config</code>.</p><h3 id="what-happens-next" tabindex="-1">What happens next <a class="header-anchor" href="#what-happens-next" aria-label="Permalink to &quot;What happens next&quot;">​</a></h3><p>The installer then:</p><ol><li>Fetches the source (when piped via <code>curl</code>) into a temp directory</li><li>Builds <code>ebpf/liteshield.bpf.o</code> and <code>bin/liteshield</code> with <code>make all</code></li><li>Installs to <code>/opt/liteshield</code> and symlinks <code>/usr/local/bin/liteshield</code></li><li>Writes <code>/etc/liteshield/liteshield.yaml</code> (mode <code>0600</code>) from your answers</li><li>Installs and offers to enable <code>liteshield-loader.service</code></li></ol><div class="info custom-block"><p class="custom-block-title">Existing config is preserved</p><p>On reinstall, your current <code>liteshield.yaml</code> is backed up to <code>liteshield.yaml.bak</code> before the new one is written.</p></div><hr><h2 id="manual-install" tabindex="-1">Manual Install <a class="header-anchor" href="#manual-install" aria-label="Permalink to &quot;Manual Install&quot;">​</a></h2><p>For full control (or non-interactive environments):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/AnAverageBeing/LiteShield-XDP</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> LiteShield-XDP</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Build the BPF object and the Go binary</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> all</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Optional: run the BPF object through the kernel verifier</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/liteshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/liteshield</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0755</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/liteshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/liteshield/liteshield</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0644</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ebpf/liteshield.bpf.o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/liteshield/liteshield.bpf.o</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ln</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/liteshield/liteshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/bin/liteshield</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Config: start from the example</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> configs/liteshield.example.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/liteshield/liteshield.yaml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 600</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/liteshield/liteshield.yaml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $EDITOR </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/etc/liteshield/liteshield.yaml</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # set interface + thresholds</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># systemd (optional)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0644</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemd/liteshield-loader.service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/systemd/system/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> daemon-reload</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --now</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> liteshield-loader.service</span></span></code></pre></div><hr><h2 id="post-install-verification" tabindex="-1">Post-Install Verification <a class="header-anchor" href="#post-install-verification" aria-label="Permalink to &quot;Post-Install Verification&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Service state (if you enabled systemd)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> liteshield-loader.service</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Counters snapshot — should show &quot;LiteShield XDP is loaded.&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> liteshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo liteshield status</span></span>
<span class="line"><span>LiteShield XDP is loaded.</span></span>
<span class="line"><span>  Packets: 104213 rx (104198 passed, 15 dropped)</span></span>
<span class="line"><span>  Rule drops: SYN 0 | UDP 12 | ICMP 3 | PPS 0 | NewSrc 0 | Ban 0</span></span>
<span class="line"><span>  Lists: whitelist hits 0 | blacklist hits 0 | active bans 0</span></span></code></pre></div><p>You can also confirm the XDP program is attached at the kernel level:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> link</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xdp</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># → prog/xdp id 42 ... (native mode shows &quot;xdp&quot;, generic shows &quot;xdpgeneric&quot;)</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Try the live screen</p><p>Run <code>sudo liteshield load</code> in a spare terminal to watch throughput, drops, and bans in real time. Quitting with <code>Ctrl-C</code> leaves the firewall running.</p></div><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>Kernel X is too old</code></td><td>Kernel &lt; 5.15</td><td>Upgrade the kernel (Ubuntu 22.04+ / Debian 12+ are fine)</td></tr><tr><td><code>/sys/kernel/btf/vmlinux not found</code></td><td>Kernel built without BTF</td><td>Use a stock distro kernel; custom kernels need <code>CONFIG_DEBUG_INFO_BTF=y</code></td></tr><tr><td><code>llvm-strip is still missing</code></td><td>Versioned binary on Debian/Ubuntu</td><td><code>sudo ln -sf $(command -v llvm-strip-14) /usr/local/bin/llvm-strip</code> (installer does this automatically)</td></tr><tr><td><code>bpftool not found</code> on Ubuntu</td><td><code>linux-tools-common</code> lacks a match for the running kernel</td><td>Install <code>linux-tools-$(uname -r)</code>; the installer falls back to this automatically</td></tr><tr><td><code>Go &gt;= 1.22 required</code></td><td>Old <code>golang-go</code> package</td><td>Install newer Go from <a href="https://go.dev/dl/" target="_blank" rel="noreferrer">go.dev</a> and re-run</td></tr><tr><td><code>liteshield status</code> says NOT loaded after boot</td><td>Service not enabled</td><td><code>sudo systemctl enable --now liteshield-loader.service</code></td></tr><tr><td>XDP attaches in generic mode unexpectedly</td><td>NIC driver lacks native XDP</td><td>Harmless — <code>xdp_mode: auto</code> falls back. Native-capable drivers: <code>ixgbe</code>, <code>i40e</code>, <code>mlx5</code>, <code>virtio_net</code>, …</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Generic mode is slower</p><p>Generic (SKB) XDP still drops floods before conntrack and your applications, but runs later than driver mode. Check the attach mode in the TUI header or <code>ip link</code> output if performance matters.</p></div><hr><h2 id="uninstall" tabindex="-1">Uninstall <a class="header-anchor" href="#uninstall" aria-label="Permalink to &quot;Uninstall&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uninstall.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # removes binary, service, BPF pins — keeps /etc/liteshield</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uninstall.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --purge</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # also removes the config directory</span></span></code></pre></div><p>The uninstaller stops <code>liteshield-loader.service</code>, detaches the XDP program, removes <code>/sys/fs/bpf/liteshield</code>, <code>/opt/liteshield</code>, and the <code>/usr/local/bin/liteshield</code> symlink. Without <code>--purge</code>, your config survives for a later reinstall.</p>`,48)])])}const u=e(n,[["render",l]]);export{k as __pageData,u as default};
